def _components(grid):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            color = grid[r][c]
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x, color))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = y + dy, x + dx
                    if (0 <= p[0] < h and 0 <= p[1] < w and
                            grid[p[0]][p[1]] == color and p not in seen):
                        seen.add(p)
                        stack.append(p)
            result.append(cells)
    return result


def _encloses_hole(cells):
    occupied = {(y, x) for y, x, _ in cells}
    y0, y1 = min(y for y, x in occupied), max(y for y, x in occupied)
    x0, x1 = min(x for y, x in occupied), max(x for y, x in occupied)
    outside = set()
    q = deque()
    for y in range(y0, y1 + 1):
        for x in range(x0, x1 + 1):
            if y in (y0, y1) or x in (x0, x1):
                if (y, x) not in occupied and (y, x) not in outside:
                    outside.add((y, x))
                    q.append((y, x))
    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = y + dy, x + dx
            if y0 <= p[0] <= y1 and x0 <= p[1] <= x1 and p not in occupied and p not in outside:
                outside.add(p)
                q.append(p)
    return any((y, x) not in occupied and (y, x) not in outside
               for y in range(y0, y1 + 1) for x in range(x0, x1 + 1))


def transform(grid):
    h, w = len(grid), len(grid[0])
    objs = [{"cells": c, "up": _encloses_hole(c)} for c in _components(grid)]
    for up in (True, False):
        occupied = []
        group = [o for o in objs if o["up"] == up]
        group.sort(key=lambda o: min(y for y, x, _ in o["cells"]) if up
                   else -max(y for y, x, _ in o["cells"]))
        dy = -1 if up else 1
        for obj in group:
            cells = obj["cells"]
            shift = 0
            while True:
                moved = {(y + shift + dy, x) for y, x, _ in cells}
                if any(y < 0 or y >= h for y, x in moved):
                    break
                if any(moved & prior for prior in occupied):
                    break
                shift += dy
            obj["shift"] = shift
            occupied.append({(y + shift, x) for y, x, _ in cells})
    out = [[0] * w for _ in range(h)]
    for obj in objs:
        for y, x, color in obj["cells"]:
            out[y + obj["shift"]][x] = color
    return out
